selector_to_html = {"a[href=\"#usage-example\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Usage example<a class=\"headerlink\" href=\"#usage-example\" title=\"Link to this heading\">#</a></h3><p><a data-lightbox=\"image-set\" href=\"../_images/cuda-side.PNG\">\n<img alt=\"alt text\" src=\"../_images/cuda-side.PNG\"/></a>\n</p>", "a[href=\"#llvm-route\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">LLVM route<a class=\"headerlink\" href=\"#llvm-route\" title=\"Link to this heading\">#</a></h3><p>Basic flow: use clang to translate CUDA code into LLVM IR, then apply the existing LLVM inline pass.</p><p><a data-lightbox=\"image-set\" href=\"../_images/cuda-to-vllm-line-pass.png\">\n<img alt=\"alt text\" src=\"../_images/cuda-to-vllm-line-pass.png\"/></a>\n</p>", "a[href=\"#use-tle-raw\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-Raw<a class=\"headerlink\" href=\"#use-tle-raw\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-Raw. TLE-Raw is available on trition_3.6.x branch.</p><p>TLE Raw provides a low-level extension interface for Triton, allowing users to fill capability gaps and gain fine-grained control via third-party dialects and languages (for example, using CUDA for thread-level scheduling, synchronization, and memory access). Users can choose between portability and composable optimization (via MLIR dialect integration) and maximum fine-grained control (via CUDA  integration) based on the target hardware and toolchain maturity.</p>", "a[href=\"#multi-gpu-communication-with-nvshmem\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-GPU communication with NVSHMEM<a class=\"headerlink\" href=\"#multi-gpu-communication-with-nvshmem\" title=\"Link to this heading\">#</a></h3><p>NVSHMEM is NVIDIA\u2019s PGAS (Partitioned Global Address Space) communication library for multi-GPU and multi-node programs. It gives every rank a unified address space: a region of memory on each GPU (symmetric memory) is reachable both from the local GPU and directly from other GPUs, so cross-GPU communication can be expressed with ordinary load/store or put/get semantics instead of hand-written point-to-point send/receive logic. It provides both host-side and device-side APIs, and the device-side interfaces can be called from inside a kernel, which makes it a natural fit for all-gather, all-reduce, and fused GEMM-plus-communication patterns. NVSHMEM is used only for NVIDIA GPUs; the distributed primitives of TLE-Lite and TLE-Struct use FlagCX instead of NVSHMEM.</p><p>On top of the CUDA integration, <code class=\"docutils literal notranslate\"><span class=\"pre\">@dialect</span></code> adds the <code class=\"docutils literal notranslate\"><span class=\"pre\">library</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">compiler</span></code> parameters so that NVSHMEM device-side interfaces can be inlined directly into a TLE-Raw kernel:</p>", "a[href=\"#frontend-cuda-llvm-integration-into-triton-frontend-and-runtime\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Frontend: CUDA-LLVM integration into Triton frontend and runtime<a class=\"headerlink\" href=\"#frontend-cuda-llvm-integration-into-triton-frontend-and-runtime\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#processing-flow\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Processing flow<a class=\"headerlink\" href=\"#processing-flow\" title=\"Link to this heading\">#</a></h3><h4>Frontend: CUDA-LLVM integration into Triton frontend and runtime<a class=\"headerlink\" href=\"#frontend-cuda-llvm-integration-into-triton-frontend-and-runtime\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#semantic-object-mapping\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Semantic object mapping<a class=\"headerlink\" href=\"#semantic-object-mapping\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#middle-end-python-to-c-mlir-pass-relationship-and-pass-inheritance\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Middle-End: Python to C++, MLIR pass relationship and pass inheritance<a class=\"headerlink\" href=\"#middle-end-python-to-c-mlir-pass-relationship-and-pass-inheritance\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#backend-cuda-llvm-ir-conversion-parameter-handling-and-triton-tle-raw-data-bridging\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Backend: CUDA-LLVM IR conversion \u2014 parameter handling and Triton/TLE-Raw data bridging<a class=\"headerlink\" href=\"#backend-cuda-llvm-ir-conversion-parameter-handling-and-triton-tle-raw-data-bridging\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#integrate-mlir-dialect-into-llvm-for-portability-and-composable-optimization\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Integrate MLIR dialect into LLVM for portability and composable optimization<a class=\"headerlink\" href=\"#integrate-mlir-dialect-into-llvm-for-portability-and-composable-optimization\" title=\"Link to this heading\">#</a></h2><p>The following is an example of MLIR (Multi-Level Intermediate Representation).</p>", "a[href=\"#integrate-cuda-into-llvm-for-maximum-fine-grained-control\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Integrate CUDA into LLVM for maximum fine-grained control<a class=\"headerlink\" href=\"#integrate-cuda-into-llvm-for-maximum-fine-grained-control\" title=\"Link to this heading\">#</a></h2><p>This section only covers how to integrate CUDA kernel into LLVM inline path. Integrating other vendors into LLVM inline path can follow similar steps.</p><p>TLE-Raw supports CUDA kernel integration via the LLVM inline path. Vendors integrating TLE-Raw on the CUDA side should evaluate:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
